[RequireComponent(typeof(Terrain))]
public class TerrainGenerator13 : MonoBehaviour
{
    [SerializeField] int resolution = 256;
    [SerializeField] float maxHeight = 40f;
    [SerializeField] float scale = 25f;
    [SerializeField] int octaves = 4;

