**Plan**
- A Rigidbody2D controller with horizontal acceleration/deceleration, a jump with variable height (releasing the button early cuts the upward speed) and stronger gravity when falling.
- Coyote time lets you still jump for 0.1 s after walking off a ledge, and a jump buffer remembers a jump press made up to 0.12 s before landing.
- Ground is detected with a thin `OverlapBox` just below the collider, ignoring triggers and the player itself.

```csharp
using UnityEngine;

[RequireComponent(typeof(Rigidbody2D), typeof(BoxCollider2D))]
public class PlatformerController2D : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 8f;
    [SerializeField] private float acceleration = 70f;
    [SerializeField] private float deceleration = 90f;
    [SerializeField] private float jumpVelocity = 14f;
    [SerializeField] private float coyoteTime = 0.1f;
    [SerializeField] private float jumpBufferTime = 0.12f;
    [SerializeField] private float fallGravityMultiplier = 2.2f;
    [SerializeField] private float jumpCutMultiplier = 0.5f;
    [SerializeField] private float groundCheckDistance = 0.06f;
    [SerializeField] private LayerMask groundMask = ~0;

    private Rigidbody2D body;
    private BoxCollider2D box;
    private float inputX;
    private float coyoteCounter;
    private float bufferCounter;
    private float baseGravity;

    public bool Grounded { get; private set; }

    private void Awake()
    {
        body = GetComponent<Rigidbody2D>();
        box = GetComponent<BoxCollider2D>();
        body.freezeRotation = true;
        baseGravity = body.gravityScale;
    }

    private void Update()
    {
        inputX = Input.GetAxisRaw("Horizontal");
        Grounded = CheckGround();

        coyoteCounter = Grounded ? coyoteTime : coyoteCounter - Time.deltaTime;
        if (Input.GetButtonDown("Jump")) bufferCounter = jumpBufferTime;
        else bufferCounter -= Time.deltaTime;

        if (bufferCounter > 0f && coyoteCounter > 0f)
        {
            body.velocity = new Vector2(body.velocity.x, jumpVelocity);
            bufferCounter = 0f;
            coyoteCounter = 0f;
        }

        if (Input.GetButtonUp("Jump") && body.velocity.y > 0f)
            body.velocity = new Vector2(body.velocity.x, body.velocity.y * jumpCutMultiplier);
    }

    private void FixedUpdate()
    {
        float target = inputX * moveSpeed;
        float rate = Mathf.Abs(target) > 0.01f ? acceleration : deceleration;
        float vx = Mathf.MoveTowards(body.velocity.x, target, rate * Time.fixedDeltaTime);
        body.velocity = new Vector2(vx, body.velocity.y);
        body.gravityScale = body.velocity.y < -0.1f ? baseGravity * fallGravityMultiplier : baseGravity;
    }

    private bool CheckGround()
    {
        Bounds b = box.bounds;
        Vector2 center = new Vector2(b.center.x, b.min.y - groundCheckDistance * 0.5f);
        Vector2 size = new Vector2(b.size.x * 0.9f, groundCheckDistance);
        foreach (Collider2D hit in Physics2D.OverlapBoxAll(center, size, 0f, groundMask))
        {
            if (hit.isTrigger || hit.gameObject == gameObject) continue;
            return true;
        }
        return false;
    }
}
```

Coyote time and the jump buffer are just two countdown timers. The coyote timer is refilled every frame the player stands on ground, and the buffer timer is refilled on a jump press; a jump happens whenever both are above zero, so a press just before landing and a press just after leaving a ledge both work. The jump cut on release gives short hops for taps and full jumps for held presses.

**Plan**
- A MonoBehaviour that adds a UIDocument (with runtime PanelSettings) and builds the menu in code with new Button() and new Label().
- Play loads the game scene; Continue is disabled unless a save flag exists in PlayerPrefs; Quit exits the application.
- Settings swaps the menu for a small panel with a Back button, all in the same root.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

public class MainMenuUI : MonoBehaviour
{
    [SerializeField] private string gameSceneName = "Game";
    [SerializeField] private string saveKey = "HasSave";

    private VisualElement root;
    private VisualElement menuPanel;
    private VisualElement settingsPanel;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;
        root.style.backgroundColor = new Color(0.07f, 0.08f, 0.12f, 1f);

        menuPanel = BuildMenu();
        settingsPanel = BuildSettingsPanel();
        settingsPanel.style.display = DisplayStyle.None;
        root.Add(menuPanel);
        root.Add(settingsPanel);
    }

    private VisualElement BuildMenu()
    {
        VisualElement panel = new VisualElement();
        panel.style.alignItems = Align.Center;

        Label title = new Label("SHADOW RUNNER");
        title.style.fontSize = 72;
        title.style.unityFontStyleAndWeight = FontStyle.Bold;
        title.style.color = Color.white;
        title.style.marginBottom = 50;
        panel.Add(title);

        panel.Add(MakeButton("Play", OnPlay));

        Button continueButton = MakeButton("Continue", OnContinue);
        bool hasSave = PlayerPrefs.GetInt(saveKey, 0) == 1;
        continueButton.SetEnabled(hasSave);
        continueButton.style.opacity = hasSave ? 1f : 0.4f;
        panel.Add(continueButton);

        panel.Add(MakeButton("Settings", () => ShowSettings(true)));
        panel.Add(MakeButton("Quit", OnQuit));
        return panel;
    }

    private VisualElement BuildSettingsPanel()
    {
        VisualElement panel = new VisualElement();
        panel.style.alignItems = Align.Center;

        Label header = new Label("Settings");
        header.style.fontSize = 56;
        header.style.color = Color.white;
        header.style.marginBottom = 30;
        panel.Add(header);

        Toggle muteToggle = new Toggle("Mute audio");
        muteToggle.value = AudioListener.pause;
        muteToggle.style.color = Color.white;
        muteToggle.style.fontSize = 28;
        muteToggle.RegisterValueChangedCallback(evt => AudioListener.pause = evt.newValue);
        panel.Add(muteToggle);

        panel.Add(MakeButton("Back", () => ShowSettings(false)));
        return panel;
    }

    private Button MakeButton(string text, Action onClick)
    {
        Button button = new Button(onClick);
        button.text = text;
        button.style.width = 360;
        button.style.height = 70;
        button.style.fontSize = 30;
        button.style.marginBottom = 14;
        button.style.color = Color.white;
        button.style.backgroundColor = new Color(0.2f, 0.35f, 0.75f, 1f);
        button.style.borderTopLeftRadius = 10;
        button.style.borderTopRightRadius = 10;
        button.style.borderBottomLeftRadius = 10;
        button.style.borderBottomRightRadius = 10;
        return button;
    }

    private void ShowSettings(bool show)
    {
        menuPanel.style.display = show ? DisplayStyle.None : DisplayStyle.Flex;
        settingsPanel.style.display = show ? DisplayStyle.Flex : DisplayStyle.None;
    }

    private void OnPlay()
    {
        PlayerPrefs.SetInt(saveKey, 1);
        PlayerPrefs.Save();
        SceneManager.LoadScene(gameSceneName);
    }

    private void OnContinue()
    {
        SceneManager.LoadScene(gameSceneName);
    }

    private void OnQuit()
    {
        Application.Quit();
    }
}
```

Attach MainMenuUI to an empty GameObject and set the game scene name; the component creates its own UIDocument and PanelSettings at runtime. Continue is created disabled and dimmed unless the PlayerPrefs "HasSave" flag is 1, which Play sets. Settings and the main menu are two panels in the same root that are toggled with display styles.

**Plan**
- Build a settings panel in code with two Slider controls (master volume, mouse sensitivity) and a Toggle (fullscreen).
- Load stored values from PlayerPrefs on enable and apply them immediately (AudioListener.volume, Screen.fullScreen).
- Save on every change and expose the sensitivity through a public static property so other scripts can read it.

```csharp
using System;
using UnityEngine;
using UnityEngine.UIElements;

public class SettingsMenuUI : MonoBehaviour
{
    private const string VolumeKey = "Settings.MasterVolume";
    private const string SensitivityKey = "Settings.MouseSensitivity";
    private const string FullscreenKey = "Settings.Fullscreen";

    public static float MouseSensitivity { get; private set; } = 2f;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        float volume = PlayerPrefs.GetFloat(VolumeKey, 1f);
        float sensitivity = PlayerPrefs.GetFloat(SensitivityKey, 2f);
        bool fullscreen = PlayerPrefs.GetInt(FullscreenKey, Screen.fullScreen ? 1 : 0) == 1;
        ApplyVolume(volume);
        MouseSensitivity = sensitivity;
        Screen.fullScreen = fullscreen;

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;
        root.style.backgroundColor = new Color(0.08f, 0.09f, 0.13f, 1f);

        VisualElement card = new VisualElement();
        card.style.width = 640;
        card.style.paddingTop = 30;
        card.style.paddingBottom = 30;
        card.style.paddingLeft = 40;
        card.style.paddingRight = 40;
        card.style.backgroundColor = new Color(0.14f, 0.16f, 0.22f, 1f);
        card.style.borderTopLeftRadius = 16;
        card.style.borderTopRightRadius = 16;
        card.style.borderBottomLeftRadius = 16;
        card.style.borderBottomRightRadius = 16;
        root.Add(card);

        Label title = new Label("Settings");
        title.style.fontSize = 48;
        title.style.color = Color.white;
        title.style.marginBottom = 24;
        card.Add(title);

        Slider volumeSlider = MakeSlider(card, "Master Volume", 0f, 1f, volume, value =>
        {
            ApplyVolume(value);
            PlayerPrefs.SetFloat(VolumeKey, value);
            PlayerPrefs.Save();
        });
        volumeSlider.name = "VolumeSlider";

        MakeSlider(card, "Mouse Sensitivity", 0.1f, 10f, sensitivity, value =>
        {
            MouseSensitivity = value;
            PlayerPrefs.SetFloat(SensitivityKey, value);
            PlayerPrefs.Save();
        });

        Toggle fullscreenToggle = new Toggle("Fullscreen");
        fullscreenToggle.value = fullscreen;
        fullscreenToggle.style.fontSize = 26;
        fullscreenToggle.style.color = Color.white;
        fullscreenToggle.RegisterValueChangedCallback(evt =>
        {
            Screen.fullScreen = evt.newValue;
            PlayerPrefs.SetInt(FullscreenKey, evt.newValue ? 1 : 0);
            PlayerPrefs.Save();
        });
        card.Add(fullscreenToggle);
    }

    private static Slider MakeSlider(VisualElement parent, string labelText, float min, float max, float start, Action<float> onChange)
    {
        Label label = new Label(labelText + ": " + start.ToString("0.00"));
        label.style.fontSize = 26;
        label.style.color = Color.white;
        label.style.marginTop = 10;
        parent.Add(label);

        Slider slider = new Slider(min, max);
        slider.value = start;
        slider.style.marginBottom = 16;
        slider.RegisterValueChangedCallback(evt =>
        {
            label.text = labelText + ": " + evt.newValue.ToString("0.00");
            onChange(evt.newValue);
        });
        parent.Add(slider);
        return slider;
    }

    private static void ApplyVolume(float value)
    {
        AudioListener.volume = Mathf.Clamp01(value);
    }
}
```

Each slider is created by a helper that updates its own label, calls the supplied callback, and the callbacks write to PlayerPrefs and apply the setting immediately. On enable the saved values are read back and applied before the UI is built, so the controls start at the stored positions. Other scripts can read `SettingsMenuUI.MouseSensitivity` for their look code.

