[Serializable]
public class LevelEntry
{
    public string displayName = "Level";
    public string sceneName = "Level1";
}

public class LevelSelectUI : MonoBehaviour
{
    public const string UnlockedKey = "UnlockedLevels";

    [SerializeField] private List<LevelEntry> levels = new List<LevelEntry>
    {
        new LevelEntry { displayName = "Level 1", sceneName = "Level1" },
        new LevelEntry { displayName = "Level 2", sceneName = "Level2" },
        new LevelEntry { displayName = "Level 3", sceneName = "Level3" },
    };

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.paddingTop = 60;
        root.style.backgroundColor = new Color(0.07f, 0.09f, 0.13f, 1f);

        Label title = new Label("Select Level");
        title.style.fontSize = 60;
        title.style.color = Color.white;
        title.style.marginBottom = 30;
        root.Add(title);

        ScrollView list = new ScrollView();
        list.style.width = 520;
        list.style.flexGrow = 1;
        root.Add(list);

        int unlocked = Mathf.Max(1, PlayerPrefs.GetInt(UnlockedKey, 1));
        for (int i = 0; i < levels.Count; i++)
        {
            list.Add(BuildLevelButton(levels[i], i < unlocked));
        }
    }

    private Button BuildLevelButton(LevelEntry entry, bool isUnlocked)
    {
        string sceneName = entry.sceneName;
        Button button = new Button(() => SceneManager.LoadScene(sceneName));
        button.text = isUnlocked ? entry.displayName : entry.displayName + "   [LOCKED]";
        button.style.height = 70;
        button.style.fontSize = 30;
        button.style.marginBottom = 12;
        button.style.color = isUnlocked ? Color.white : new Color(0.6f, 0.6f, 0.6f, 1f);
        button.style.backgroundColor = isUnlocked
            ? new Color(0.2f, 0.45f, 0.8f, 1f)
            : new Color(0.2f, 0.2f, 0.25f, 1f);
        button.SetEnabled(isUnlocked);
        return button;
    }

    public static void UnlockUpTo(int levelCount)
    {
        int current = PlayerPrefs.GetInt(UnlockedKey, 1);
        if (levelCount > current)
        {
            PlayerPrefs.SetInt(UnlockedKey, levelCount);
            PlayerPrefs.Save();
        }
    }
}
```

The list of levels is edited in the inspector; the menu creates one button per entry and compares its index to the unlocked count stored in PlayerPrefs. Locked buttons are disabled, greyed and labelled. `LevelSelectUI.UnlockUpTo(n)` is a static helper a level-complete script can call to raise the unlocked count.

